package com.franco.desco.application.census.service;import com.franco.desco.application.census.CensusCommands.*;import com.franco.desco.application.census.port.in.CensusUseCase;import com.franco.desco.application.census.port.out.CensusPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.census.CensusModels;public final class CensusApplicationService implements CensusUseCase{private final CensusPersistencePort p;public CensusApplicationService(CensusPersistencePort p){this.p=p;}public AppResult<PageResult<CensusModels.Summary>>list(ListCensuses c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.list(c,i,m),"CENSOS_LISTADOS","CENSOS_NO_LISTADOS",AppStatus.BAD_REQUEST);}public AppResult<Long>create(CreateCensus c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.create(c,i,m),"CENSO_CREADO","CENSO_NO_CREADO");}public AppResult<Void>update(UpdateCensus c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.update(c,i,m),"CENSO_ACTUALIZADO","CENSO_NO_ACTUALIZADO",AppStatus.BAD_REQUEST);}}
